-- Hosbah queries.

-- name: RecordServerMetric :exec
-- Agent scope: one minute of readings, already averaged by the control plane (@samples of them).
-- If the minute already has a row (a reconnect within the minute), the two are merged, weighted
-- by samples; memory and disk keep the newer reading, GPUs the newer non-empty one.
INSERT INTO server_metrics (server_id, team_id, at, step, samples, cpu_percent, mem_used, mem_total, disk_used, disk_total, load1, net_rx, net_tx, gpu)
VALUES (sqlc.arg('server_id'), sqlc.arg('team_id'), sqlc.arg('at'), 60, sqlc.arg('samples'), sqlc.arg('cpu_percent'), sqlc.arg('mem_used'), sqlc.arg('mem_total'),
    sqlc.arg('disk_used'), sqlc.arg('disk_total'), sqlc.arg('load1'), sqlc.arg('net_rx'), sqlc.arg('net_tx'), sqlc.arg('gpu')::jsonb)
ON CONFLICT (server_id, step, at) DO UPDATE SET
    cpu_percent = (server_metrics.cpu_percent * server_metrics.samples + EXCLUDED.cpu_percent * EXCLUDED.samples) / (server_metrics.samples + EXCLUDED.samples),
    load1 = (server_metrics.load1 * server_metrics.samples + EXCLUDED.load1 * EXCLUDED.samples) / (server_metrics.samples + EXCLUDED.samples),
    net_rx = (server_metrics.net_rx * server_metrics.samples + EXCLUDED.net_rx * EXCLUDED.samples) / (server_metrics.samples + EXCLUDED.samples),
    net_tx = (server_metrics.net_tx * server_metrics.samples + EXCLUDED.net_tx * EXCLUDED.samples) / (server_metrics.samples + EXCLUDED.samples),
    mem_used = EXCLUDED.mem_used, mem_total = EXCLUDED.mem_total,
    disk_used = EXCLUDED.disk_used, disk_total = EXCLUDED.disk_total,
    gpu = CASE WHEN jsonb_array_length(EXCLUDED.gpu) > 0 THEN EXCLUDED.gpu ELSE server_metrics.gpu END,
    samples = server_metrics.samples + EXCLUDED.samples, updated_at = now();

-- name: ServerMetricsSince :many
-- Team scope: one server's samples (minute and 15-minute rows) since a time, oldest first.
SELECT at, step, samples, cpu_percent, mem_used, mem_total, disk_used, disk_total, load1, net_rx, net_tx, gpu
FROM server_metrics
WHERE server_id = sqlc.arg('server_id') AND team_id = sqlc.arg('team_id') AND at >= sqlc.arg('since')
ORDER BY at;

-- name: TeamServerMetricsSince :many
-- Team scope: every server's samples since a time (the home page's sparklines), oldest first.
SELECT server_id, at, samples, cpu_percent, mem_used, mem_total, disk_used, disk_total, load1, net_rx, net_tx, gpu
FROM server_metrics
WHERE team_id = sqlc.arg('team_id') AND at >= sqlc.arg('since')
ORDER BY server_id, at;

-- name: CompactServerMetrics :execrows
-- System scope (the retention job): minute rows older than @before become 15-minute rows. A
-- 15-minute bucket that straddles @before is merged across runs (sample-weighted), so a bucket
-- ends up the same as if it had been compacted at once. GPUs are averaged per index.
WITH moved AS (
    DELETE FROM server_metrics sm WHERE sm.step = 60 AND sm.at < sqlc.arg('before')::timestamptz
    RETURNING sm.server_id, sm.team_id, sm.at, sm.samples, sm.cpu_percent, sm.mem_used, sm.mem_total, sm.disk_used, sm.disk_total,
        sm.load1, sm.net_rx, sm.net_tx, sm.gpu
), b AS (
    SELECT mv.server_id, mv.team_id, to_timestamp(floor(extract(epoch FROM mv.at) / 900) * 900) AS bucket, mv.samples,
        mv.cpu_percent, mv.mem_used, mv.mem_total, mv.disk_used, mv.disk_total, mv.load1, mv.net_rx, mv.net_tx, mv.gpu
    FROM moved mv
), per_gpu AS (
    SELECT b.server_id, b.bucket, (e.value->>'index')::int AS idx,
        avg((e.value->>'util')::float8) AS util, avg((e.value->>'mem_used')::float8) AS mem_used,
        max((e.value->>'mem_total')::float8) AS mem_total, avg((e.value->>'temp')::float8) AS temp
    FROM b, jsonb_array_elements(CASE WHEN jsonb_typeof(b.gpu) = 'array' THEN b.gpu ELSE '[]'::jsonb END) AS e
    GROUP BY b.server_id, b.bucket, (e.value->>'index')::int
), g AS (
    SELECT per_gpu.server_id, per_gpu.bucket, jsonb_agg(jsonb_build_object('index', per_gpu.idx, 'util', round(per_gpu.util::numeric, 1),
        'mem_used', round(per_gpu.mem_used::numeric), 'mem_total', per_gpu.mem_total, 'temp', round(per_gpu.temp::numeric, 1)) ORDER BY per_gpu.idx) AS gpu
    FROM per_gpu GROUP BY per_gpu.server_id, per_gpu.bucket
), agg AS (
    SELECT b.server_id, b.team_id, b.bucket, sum(b.samples)::bigint AS samples,
        sum(b.cpu_percent * b.samples) / sum(b.samples) AS cpu_percent,
        avg(b.mem_used)::bigint AS mem_used, max(b.mem_total)::bigint AS mem_total,
        avg(b.disk_used)::bigint AS disk_used, max(b.disk_total)::bigint AS disk_total,
        sum(b.load1 * b.samples) / sum(b.samples) AS load1,
        sum(b.net_rx * b.samples) / sum(b.samples) AS net_rx,
        sum(b.net_tx * b.samples) / sum(b.samples) AS net_tx
    FROM b GROUP BY b.server_id, b.team_id, b.bucket
)
INSERT INTO server_metrics (server_id, team_id, at, step, samples, cpu_percent, mem_used, mem_total, disk_used, disk_total, load1, net_rx, net_tx, gpu)
SELECT agg.server_id, agg.team_id, agg.bucket, 900, agg.samples, agg.cpu_percent, agg.mem_used, agg.mem_total, agg.disk_used, agg.disk_total,
    agg.load1, agg.net_rx, agg.net_tx, coalesce(g.gpu, '[]'::jsonb)
FROM agg LEFT JOIN g ON g.server_id = agg.server_id AND g.bucket = agg.bucket
ON CONFLICT (server_id, step, at) DO UPDATE SET
    cpu_percent = (server_metrics.cpu_percent * server_metrics.samples + EXCLUDED.cpu_percent * EXCLUDED.samples) / (server_metrics.samples + EXCLUDED.samples),
    load1 = (server_metrics.load1 * server_metrics.samples + EXCLUDED.load1 * EXCLUDED.samples) / (server_metrics.samples + EXCLUDED.samples),
    net_rx = (server_metrics.net_rx * server_metrics.samples + EXCLUDED.net_rx * EXCLUDED.samples) / (server_metrics.samples + EXCLUDED.samples),
    net_tx = (server_metrics.net_tx * server_metrics.samples + EXCLUDED.net_tx * EXCLUDED.samples) / (server_metrics.samples + EXCLUDED.samples),
    mem_used = (server_metrics.mem_used * server_metrics.samples + EXCLUDED.mem_used * EXCLUDED.samples) / (server_metrics.samples + EXCLUDED.samples),
    disk_used = (server_metrics.disk_used * server_metrics.samples + EXCLUDED.disk_used * EXCLUDED.samples) / (server_metrics.samples + EXCLUDED.samples),
    mem_total = greatest(server_metrics.mem_total, EXCLUDED.mem_total),
    disk_total = greatest(server_metrics.disk_total, EXCLUDED.disk_total),
    gpu = CASE WHEN jsonb_array_length(EXCLUDED.gpu) > 0 THEN EXCLUDED.gpu ELSE server_metrics.gpu END,
    samples = server_metrics.samples + EXCLUDED.samples, updated_at = now();

-- name: PruneServerMetrics :execrows
-- System scope (the retention job): 15-minute rows older than @before are dropped.
DELETE FROM server_metrics WHERE step = 900 AND at < sqlc.arg('before')::timestamptz;
